import{_ as t,c as n,j as e,a as r,o}from"./chunks/framework.CqbvlPrP.js";const f=JSON.parse('{"title":"第二百七十章 燃烧的大火","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/270第二百七十章 燃烧的大火.md","filePath":"meditation/巴利文大藏经/270第二百七十章 燃烧的大火.md"}'),_={name:"meditation/巴利文大藏经/270第二百七十章 燃烧的大火.md"};function l(s,a,i,d,c,p){return o(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百七十章-燃烧的大火",tabindex:"-1"},[r("第二百七十章 燃烧的大火 "),e("a",{class:"header-anchor",href:"#第二百七十章-燃烧的大火","aria-label":'Permalink to "第二百七十章 燃烧的大火"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应61经/燃烧经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人），物质事物、物质身体、感受、念想、行为、认识、分别、判断就如同身上熊熊燃烧的大火，如果不赶快扑灭大火，就会被大火烧死。比丘们！当你们生起这样见解的时候，就是已经受到如来教导的圣弟子，你们不要执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断。不执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，那么自己的心念就不会被扰动、污染。由于灭尽贪欲、渴爱的缘故就能从物质事物、物质身体、感受、念想、行为、认识、分别、判断中解脱出来，从一切烦恼和痛苦中解脱出来。当解脱的时候，就能开启解脱的智慧，就能证悟解脱的果位，那时自己就明白了：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生在世间了，已经彻底从生死轮回中解脱出来。」”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const u=t(_,[["render",l]]);export{f as __pageData,u as default};
